-- Phase 9B: immutable Festival results and historical legacy. No runtime or finance mechanics live here.
CREATE TABLE public.festival_results (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), festival_settlement_id uuid NOT NULL UNIQUE REFERENCES public.festival_financial_settlements(id),
 runtime_outcome_snapshot_id uuid NOT NULL UNIQUE REFERENCES public.festival_runtime_outcome_snapshots(id), settlement_snapshot_id uuid NOT NULL UNIQUE REFERENCES public.festival_settlement_snapshots(id),
 festival_launch_id uuid NOT NULL UNIQUE REFERENCES public.festival_launches(id), festival_edition_id uuid NOT NULL, festival_company_id uuid NOT NULL REFERENCES public.festival_companies(id),
 festival_name text NOT NULL, edition_year integer NOT NULL, country text NOT NULL DEFAULT '', city text NOT NULL DEFAULT '', festival_type text NOT NULL DEFAULT 'local', genres text[] NOT NULL DEFAULT '{}',
 attendance integer NOT NULL CHECK(attendance>=0), peak_attendance integer NOT NULL CHECK(peak_attendance>=0), revenue_minor bigint NOT NULL, profit_loss_minor bigint NOT NULL, currency_code text NOT NULL,
 sold_out boolean NOT NULL, crowd_satisfaction numeric NOT NULL CHECK(crowd_satisfaction BETWEEN 0 AND 100), weather_summary text NOT NULL, incident_summary text NOT NULL,
 performance_highlights jsonb NOT NULL DEFAULT '[]', headliner_performance jsonb NOT NULL DEFAULT '{}', sponsor_summary jsonb NOT NULL DEFAULT '{}', merchandise_summary jsonb NOT NULL DEFAULT '{}', food_drink_summary jsonb NOT NULL DEFAULT '{}'),
 headliners text[] NOT NULL DEFAULT '{}', poster_url text, timetable jsonb NOT NULL DEFAULT '[]', source_digests jsonb NOT NULL, result_version text NOT NULL DEFAULT 'festival-legacy-v1', published_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE public.festival_reviews (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), festival_result_id uuid NOT NULL UNIQUE REFERENCES public.festival_results(id), organisation numeric NOT NULL, line_up numeric NOT NULL, crowd_atmosphere numeric NOT NULL,
 stage_production numeric NOT NULL, value_for_money numeric NOT NULL, food_drink numeric NOT NULL, facilities numeric NOT NULL, overall_rating numeric NOT NULL CHECK(overall_rating BETWEEN 0 AND 100), review_version text NOT NULL DEFAULT 'festival-review-v1', published_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE public.festival_reputation_changes (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), festival_result_id uuid NOT NULL REFERENCES public.festival_results(id), subject_type text NOT NULL CHECK(subject_type IN('festival_company','festival_brand','artist','band','sponsor','staff','supplier','venue','host_city')),
 subject_id uuid, change numeric NOT NULL, resulting_reputation numeric, factors jsonb NOT NULL, formula_version text NOT NULL DEFAULT 'festival-reputation-v1', applied_at timestamptz NOT NULL DEFAULT now(), UNIQUE(festival_result_id,subject_type,subject_id)
);
CREATE TABLE public.festival_awards (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), season_year integer NOT NULL, category text NOT NULL CHECK(category IN('festival_of_the_year','best_small_festival','best_major_festival','best_headliner','best_performance','best_new_artist','best_crowd','best_stage_production','best_sponsor_activation','best_organised_festival')),
 festival_result_id uuid REFERENCES public.festival_results(id), winner_type text NOT NULL, winner_id uuid, winner_name text NOT NULL, score numeric NOT NULL, citation text NOT NULL, evidence jsonb NOT NULL DEFAULT '{}', awarded_at timestamptz NOT NULL DEFAULT now(), UNIQUE(season_year,category)
);
CREATE TABLE public.festival_world_records (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), category text NOT NULL UNIQUE CHECK(category IN('highest_attendance','fastest_sell_out','largest_profit','biggest_loss','highest_rated_festival','longest_running_festival','most_performances','most_merchandise_sold','largest_single_performance_crowd')),
 festival_result_id uuid NOT NULL REFERENCES public.festival_results(id), holder_name text NOT NULL, value numeric NOT NULL, unit text NOT NULL, achieved_year integer NOT NULL, evidence jsonb NOT NULL DEFAULT '{}', updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE public.festival_legacy_publications (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), festival_result_id uuid NOT NULL REFERENCES public.festival_results(id), channel text NOT NULL CHECK(channel IN('world_pulse','rockmundo_fm','twaater','player_news','band_news','company_news')),
 headline text NOT NULL, summary text NOT NULL, payload jsonb NOT NULL DEFAULT '{}', published_at timestamptz NOT NULL DEFAULT now(), UNIQUE(festival_result_id,channel)
);

CREATE FUNCTION public._deny_festival_legacy_mutation() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$BEGIN RAISE EXCEPTION 'festival_archive_is_immutable';END$$;
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['festival_results','festival_reviews','festival_reputation_changes','festival_awards','festival_legacy_publications'] LOOP EXECUTE format('CREATE TRIGGER %I_immutable BEFORE UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public._deny_festival_legacy_mutation()',t,t);END LOOP;END$$;

CREATE FUNCTION public.generate_festival_result(p_settlement_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE s public.festival_financial_settlements%ROWTYPE; o public.festival_runtime_outcome_snapshots%ROWTYPE; r public.festival_results%ROWTYPE; runtime jsonb; final_digest text; score numeric; edition uuid; festival_title text;
BEGIN
 SELECT * INTO s FROM public.festival_financial_settlements WHERE id=p_settlement_id; IF s.status<>'settled' OR s.final_snapshot_id IS NULL THEN RAISE EXCEPTION 'festival_result_requires_final_settlement';END IF;
 SELECT * INTO r FROM public.festival_results WHERE festival_settlement_id=s.id; IF FOUND THEN RETURN r.id;END IF;
 SELECT * INTO o FROM public.festival_runtime_outcome_snapshots WHERE runtime_session_id=s.runtime_session_id;
 SELECT content_digest INTO final_digest FROM public.festival_settlement_snapshots WHERE id=s.final_snapshot_id;
 IF o.id IS NULL OR final_digest IS NULL THEN RAISE EXCEPTION 'festival_result_snapshot_missing';END IF;
 runtime:=o.snapshot; score:=least(100,greatest(0,coalesce((runtime->>'crowdSatisfaction')::numeric,75)));
 SELECT pe.id,pe.name INTO edition,festival_title FROM public.festival_public_editions pe WHERE pe.festival_launch_id=s.festival_launch_id;
 INSERT INTO public.festival_results(festival_settlement_id,runtime_outcome_snapshot_id,settlement_snapshot_id,festival_launch_id,festival_edition_id,festival_company_id,festival_name,edition_year,country,city,festival_type,genres,attendance,peak_attendance,revenue_minor,profit_loss_minor,currency_code,sold_out,crowd_satisfaction,weather_summary,incident_summary,performance_highlights,headliner_performance,sponsor_summary,merchandise_summary,food_drink_summary,headliners,poster_url,timetable,source_digests)
 VALUES(s.id,o.id,s.final_snapshot_id,s.festival_launch_id,edition,s.festival_company_id,coalesce(festival_title,'Festival'),extract(year from s.settled_at)::integer,coalesce(runtime->>'country',''),coalesce(runtime->>'city',''),coalesce(runtime->>'festivalType','local'),ARRAY(SELECT jsonb_array_elements_text(coalesce(runtime->'genres','[]'))),coalesce((runtime->>'attendance')::integer,0),coalesce((runtime->>'peakAttendance')::integer,(runtime->>'attendance')::integer,0),s.total_revenue_minor,s.net_profit_loss_minor,s.currency_code,coalesce((runtime->>'soldOut')::boolean,false),score,coalesce(runtime->>'weatherSummary','Weather data unavailable'),coalesce(runtime->>'incidentSummary','No major incidents'),coalesce(runtime->'performanceHighlights','[]'),coalesce(runtime->'headlinerPerformance','{}'),coalesce(runtime->'sponsorSummary','{}'),coalesce(runtime->'merchandiseSummary','{}'),coalesce(runtime->'foodDrinkSummary','{}'),ARRAY(SELECT jsonb_array_elements_text(coalesce(runtime->'headliners','[]'))),runtime->>'posterUrl',coalesce(runtime->'timetable','[]'),jsonb_build_object('runtime',o.content_digest,'settlement',final_digest)) RETURNING * INTO r;
 INSERT INTO public.festival_reviews(festival_result_id,organisation,line_up,crowd_atmosphere,stage_production,value_for_money,food_drink,facilities,overall_rating) VALUES(r.id,score,coalesce((runtime->>'lineUpScore')::numeric,score),score,coalesce((runtime->>'stageProductionScore')::numeric,score),coalesce((runtime->>'valueScore')::numeric,score),coalesce((runtime->>'foodDrinkScore')::numeric,score),coalesce((runtime->>'facilitiesScore')::numeric,score),round((score*3+coalesce((runtime->>'lineUpScore')::numeric,score)+coalesce((runtime->>'stageProductionScore')::numeric,score)+coalesce((runtime->>'valueScore')::numeric,score)+coalesce((runtime->>'foodDrinkScore')::numeric,score)+coalesce((runtime->>'facilitiesScore')::numeric,score))/8,1));
 INSERT INTO public.festival_reputation_changes(festival_result_id,subject_type,subject_id,change,factors) VALUES(r.id,'festival_company',r.festival_company_id,round(((score-50)/10 + CASE WHEN r.sold_out THEN 2 ELSE 0 END + CASE WHEN r.profit_loss_minor>0 THEN 1 ELSE -1 END)::numeric,2),jsonb_build_object('crowdSatisfaction',score,'soldOut',r.sold_out,'financialSuccess',r.profit_loss_minor>0,'incidents',r.incident_summary));
 PERFORM public.refresh_festival_world_records(r.id);
 IF r.festival_type IN('large','major') THEN INSERT INTO public.festival_legacy_publications(festival_result_id,channel,headline,summary,payload) SELECT r.id,c,r.festival_name||' publishes its festival result',r.attendance||' fans attended; the final rating was '||score||'/100.',jsonb_build_object('route','/festivals/results','festivalResultId',r.id) FROM unnest(ARRAY['world_pulse','rockmundo_fm','twaater','player_news','band_news','company_news']) c ON CONFLICT DO NOTHING; END IF;
 RETURN r.id;
END$$;

CREATE FUNCTION public.refresh_festival_world_records(p_result_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE r public.festival_results%ROWTYPE; rating numeric;BEGIN SELECT * INTO r FROM public.festival_results WHERE id=p_result_id;SELECT overall_rating INTO rating FROM public.festival_reviews WHERE festival_result_id=r.id;
 INSERT INTO public.festival_world_records(category,festival_result_id,holder_name,value,unit,achieved_year) VALUES('highest_attendance',r.id,r.festival_name,r.attendance,'attendees',r.edition_year) ON CONFLICT(category) DO UPDATE SET festival_result_id=excluded.festival_result_id,holder_name=excluded.holder_name,value=excluded.value,achieved_year=excluded.achieved_year,updated_at=now() WHERE excluded.value>festival_world_records.value;
 INSERT INTO public.festival_world_records(category,festival_result_id,holder_name,value,unit,achieved_year) VALUES('largest_profit',r.id,r.festival_name,r.profit_loss_minor,'minor_currency_units',r.edition_year) ON CONFLICT(category) DO UPDATE SET festival_result_id=excluded.festival_result_id,holder_name=excluded.holder_name,value=excluded.value,achieved_year=excluded.achieved_year,updated_at=now() WHERE excluded.value>festival_world_records.value;
 INSERT INTO public.festival_world_records(category,festival_result_id,holder_name,value,unit,achieved_year) VALUES('biggest_loss',r.id,r.festival_name,r.profit_loss_minor,'minor_currency_units',r.edition_year) ON CONFLICT(category) DO UPDATE SET festival_result_id=excluded.festival_result_id,holder_name=excluded.holder_name,value=excluded.value,achieved_year=excluded.achieved_year,updated_at=now() WHERE excluded.value<festival_world_records.value;
 INSERT INTO public.festival_world_records(category,festival_result_id,holder_name,value,unit,achieved_year) VALUES('highest_rated_festival',r.id,r.festival_name,rating,'rating_out_of_100',r.edition_year) ON CONFLICT(category) DO UPDATE SET festival_result_id=excluded.festival_result_id,holder_name=excluded.holder_name,value=excluded.value,achieved_year=excluded.achieved_year,updated_at=now() WHERE excluded.value>festival_world_records.value;END$$;

CREATE FUNCTION public.generate_festival_season_awards(p_year integer) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE n integer;BEGIN IF auth.role()<>'service_role' AND NOT coalesce(public.has_role(auth.uid(),'admin'::public.app_role),false) THEN RAISE EXCEPTION 'festival_awards_forbidden';END IF;
 WITH candidates AS(SELECT r.*,v.overall_rating,v.organisation,v.stage_production,row_number() over(order by v.overall_rating desc,r.crowd_satisfaction desc,r.attendance desc,r.id) overall_rank FROM public.festival_results r JOIN public.festival_reviews v ON v.festival_result_id=r.id WHERE r.edition_year=p_year), categories(category) AS(VALUES('festival_of_the_year'),('best_small_festival'),('best_major_festival'),('best_headliner'),('best_performance'),('best_new_artist'),('best_crowd'),('best_stage_production'),('best_sponsor_activation'),('best_organised_festival'))
 INSERT INTO public.festival_awards(season_year,category,festival_result_id,winner_type,winner_id,winner_name,score,citation,evidence)
 SELECT p_year,c.category,x.id,CASE WHEN c.category IN('best_headliner','best_performance','best_new_artist') THEN 'artist' ELSE 'festival' END,x.id,CASE WHEN c.category IN('best_headliner','best_performance','best_new_artist') THEN coalesce(x.headliners[1],x.festival_name) ELSE x.festival_name END,CASE c.category WHEN 'best_crowd' THEN x.crowd_satisfaction WHEN 'best_stage_production' THEN x.stage_production WHEN 'best_organised_festival' THEN x.organisation ELSE x.overall_rating END,'Awarded from immutable season results and review evidence.',jsonb_build_object('resultId',x.id,'rating',x.overall_rating)
 FROM categories c CROSS JOIN LATERAL(SELECT q.* FROM candidates q WHERE (c.category<>'best_small_festival' OR q.festival_type IN('local','small')) AND (c.category<>'best_major_festival' OR q.festival_type IN('large','major')) ORDER BY CASE c.category WHEN 'best_crowd' THEN q.crowd_satisfaction WHEN 'best_stage_production' THEN q.stage_production WHEN 'best_organised_festival' THEN q.organisation ELSE q.overall_rating END DESC,q.id LIMIT 1)x ON true ON CONFLICT DO NOTHING;
 GET DIAGNOSTICS n=ROW_COUNT;RETURN n;END$$;

CREATE FUNCTION public._festival_result_json(r public.festival_results) RETURNS jsonb LANGUAGE sql STABLE AS $$SELECT jsonb_build_object('id',r.id,'festivalEditionId',r.festival_edition_id,'festivalName',r.festival_name,'editionYear',r.edition_year,'country',r.country,'city',r.city,'festivalType',r.festival_type,'genres',r.genres,'attendance',r.attendance,'peakAttendance',r.peak_attendance,'revenueMinor',r.revenue_minor,'profitLossMinor',r.profit_loss_minor,'currencyCode',r.currency_code,'soldOut',r.sold_out,'crowdSatisfaction',r.crowd_satisfaction,'overallRating',(SELECT overall_rating FROM public.festival_reviews WHERE festival_result_id=r.id),'weatherSummary',r.weather_summary,'incidentSummary',r.incident_summary,'performanceHighlights',r.performance_highlights,'headlinerPerformance',r.headliner_performance,'sponsorSummary',r.sponsor_summary,'merchandiseSummary',r.merchandise_summary,'foodDrinkSummary',r.food_drink_summary,'headliners',r.headliners,'posterUrl',r.poster_url,'publishedAt',r.published_at)$$;
CREATE FUNCTION public.get_festival_results(p_year integer DEFAULT NULL,p_country text DEFAULT NULL,p_city text DEFAULT NULL,p_festival_type text DEFAULT NULL,p_genre text DEFAULT NULL) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT coalesce(jsonb_agg(public._festival_result_json(r) ORDER BY r.edition_year desc,r.festival_name),'[]') FROM public.festival_results r WHERE (p_year IS NULL OR r.edition_year=p_year) AND (p_country IS NULL OR r.country=p_country) AND (p_city IS NULL OR r.city=p_city) AND (p_festival_type IS NULL OR r.festival_type=p_festival_type) AND (p_genre IS NULL OR p_genre=ANY(r.genres))$$;
CREATE FUNCTION public.get_festival_history(p_year integer DEFAULT NULL,p_country text DEFAULT NULL,p_city text DEFAULT NULL,p_festival_type text DEFAULT NULL,p_genre text DEFAULT NULL) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT public.get_festival_results(p_year,p_country,p_city,p_festival_type,p_genre)$$;
CREATE FUNCTION public.get_festival_awards(p_year integer DEFAULT NULL) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'seasonYear',season_year,'category',category,'winnerName',winner_name,'festivalResultId',festival_result_id,'score',score,'citation',citation) ORDER BY season_year desc,category),'[]') FROM public.festival_awards WHERE p_year IS NULL OR season_year=p_year$$;
CREATE FUNCTION public.get_festival_records() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'category',category,'holderName',holder_name,'value',value,'unit',unit,'achievedYear',achieved_year) ORDER BY category),'[]') FROM public.festival_world_records$$;
CREATE FUNCTION public.get_festival_statistics(p_year integer DEFAULT NULL,p_country text DEFAULT NULL,p_city text DEFAULT NULL,p_festival_type text DEFAULT NULL,p_genre text DEFAULT NULL) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT jsonb_build_object('editions',count(*),'attendance',coalesce(sum(attendance),0),'revenueMinor',coalesce(sum(revenue_minor),0),'profitLossMinor',coalesce(sum(profit_loss_minor),0),'averageRating',coalesce(avg((SELECT overall_rating FROM public.festival_reviews WHERE festival_result_id=r.id)),0),'sellOuts',count(*) FILTER(WHERE sold_out)) FROM public.festival_results r WHERE (p_year IS NULL OR edition_year=p_year) AND (p_country IS NULL OR country=p_country) AND (p_city IS NULL OR city=p_city) AND (p_festival_type IS NULL OR festival_type=p_festival_type) AND (p_genre IS NULL OR p_genre=ANY(genres))$$;
CREATE FUNCTION public.get_festival_hall_of_fame() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT coalesce(jsonb_agg(public._festival_result_json(r) ORDER BY v.overall_rating desc,r.attendance desc),'[]') FROM public.festival_results r JOIN public.festival_reviews v ON v.festival_result_id=r.id WHERE v.overall_rating>=90 OR EXISTS(SELECT 1 FROM public.festival_awards a WHERE a.festival_result_id=r.id)$$;

CREATE FUNCTION public._publish_festival_result_after_settlement() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$BEGIN IF new.status='settled' AND new.final_snapshot_id IS NOT NULL AND old.final_snapshot_id IS DISTINCT FROM new.final_snapshot_id THEN PERFORM public.generate_festival_result(new.id);END IF;RETURN new;END$$;
CREATE TRIGGER publish_festival_result_after_settlement AFTER UPDATE OF final_snapshot_id ON public.festival_financial_settlements FOR EACH ROW EXECUTE FUNCTION public._publish_festival_result_after_settlement();
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['festival_results','festival_reviews','festival_reputation_changes','festival_awards','festival_world_records','festival_legacy_publications'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('REVOKE ALL ON public.%I FROM PUBLIC,anon,authenticated',t);END LOOP;END$$;
REVOKE ALL ON FUNCTION public._deny_festival_legacy_mutation(),public._festival_result_json(public.festival_results),public.generate_festival_result(uuid),public.refresh_festival_world_records(uuid),public._publish_festival_result_after_settlement() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.get_festival_results(integer,text,text,text,text),public.get_festival_history(integer,text,text,text,text),public.get_festival_awards(integer),public.get_festival_records(),public.get_festival_statistics(integer,text,text,text,text),public.get_festival_hall_of_fame() TO anon,authenticated;
GRANT EXECUTE ON FUNCTION public.generate_festival_season_awards(integer) TO authenticated,service_role;
COMMENT ON TABLE public.festival_results IS 'Immutable Phase 9B archive rooted in immutable runtime and final settlement snapshots.';
